/**
 * Error boundary — catches React render errors and displays a fallback UI.
 */

import { Component, type ReactNode } from 'react';
import { __ } from '@/lib/i18n';

interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error('Schedule Anything SPA error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback;
      }

      return (
        <div className="flex items-center justify-center min-h-screen bg-gray-50">
          <div className="max-w-md p-8 bg-white rounded-lg shadow-lg text-center">
            <div className="text-4xl mb-4">⚠️</div>
            <h1 className="text-xl font-semibold text-gray-900 mb-2">
              { __( 'Something went wrong', 'schedule-anything-spa' ) }
            </h1>
            <p className="text-gray-600 mb-4">
              { this.state.error?.message ||
                __( 'An unexpected error occurred.', 'schedule-anything-spa' ) }
            </p>
            <button
              onClick={ () => window.location.reload() }
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
            >
              { __( 'Reload Page', 'schedule-anything-spa' ) }
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}
